-- Generated by generate_design.py; apply once to a fresh design database.

-- Supabase manages auth.users. Local tests provide only a minimal stub.

CREATE SCHEMA app;

CREATE SCHEMA private;

CREATE TABLE app.universities (
  university_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  code varchar(30) NOT NULL UNIQUE CHECK (code = upper(btrim(code)) AND code <> ''),
  name varchar(200) NOT NULL CHECK (btrim(name) <> ''),
  status varchar(12) NOT NULL DEFAULT 'APPROVED' CHECK (status IN ('PENDING','APPROVED')),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON COLUMN app.universities.university_id IS 'Định danh trường.';

COMMENT ON COLUMN app.universities.code IS 'Mã trường chuẩn hóa.';

COMMENT ON COLUMN app.universities.name IS 'Tên trường.';

COMMENT ON COLUMN app.universities.status IS 'Trạng thái trường.';

COMMENT ON COLUMN app.universities.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE app.university_domains (
  domain varchar(253) PRIMARY KEY NOT NULL CHECK (domain = lower(domain) AND domain ~ '^[a-z0-9][a-z0-9.-]*[.]edu[.]vn$'),
  university_id uuid NOT NULL REFERENCES app.universities(university_id) ON DELETE RESTRICT
);

COMMENT ON COLUMN app.university_domains.domain IS 'Tên miền chính xác, chữ thường, không có @.';

COMMENT ON COLUMN app.university_domains.university_id IS 'Trường sở hữu tên miền.';

CREATE TABLE app.campuses (
  campus_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  university_id uuid NOT NULL REFERENCES app.universities(university_id) ON DELETE RESTRICT,
  name varchar(150) NOT NULL CHECK (btrim(name) <> ''),
  address text NOT NULL CHECK (btrim(address) <> ''),
  is_active boolean NOT NULL DEFAULT true
);

COMMENT ON COLUMN app.campuses.campus_id IS 'Định danh cơ sở.';

COMMENT ON COLUMN app.campuses.university_id IS 'Trường sở hữu.';

COMMENT ON COLUMN app.campuses.name IS 'Tên cơ sở.';

COMMENT ON COLUMN app.campuses.address IS 'Địa chỉ cơ sở.';

COMMENT ON COLUMN app.campuses.is_active IS 'Còn được chọn cho bài mới.';

CREATE TABLE app.categories (
  category_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  name varchar(100) NOT NULL CHECK (btrim(name) <> ''),
  is_active boolean NOT NULL DEFAULT true
);

COMMENT ON COLUMN app.categories.category_id IS 'Định danh danh mục.';

COMMENT ON COLUMN app.categories.name IS 'Tên danh mục.';

COMMENT ON COLUMN app.categories.is_active IS 'Danh mục được hiển thị trong form.';

CREATE TABLE app.users (
  user_id uuid PRIMARY KEY NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  full_name varchar(150) NOT NULL CHECK (btrim(full_name) <> ''),
  role varchar(10) NOT NULL DEFAULT 'STUDENT' CHECK (role IN ('STUDENT','ADMIN')),
  status varchar(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','BANNED')),
  is_verified boolean NOT NULL DEFAULT false,
  student_id varchar(30),
  failed_login_count smallint NOT NULL DEFAULT 0 CHECK (failed_login_count BETWEEN 0 AND 5),
  login_locked_until timestamptz,
  ban_reason text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT users_ban_reason CHECK (status <> 'BANNED' OR nullif(btrim(ban_reason),'') IS NOT NULL)
);

COMMENT ON COLUMN app.users.user_id IS 'Cùng UUID với auth.users; không tự sinh identity thứ hai.';

COMMENT ON COLUMN app.users.full_name IS 'Họ tên.';

COMMENT ON COLUMN app.users.role IS 'Vai trò lưu trong CSDL; Guest không có bản ghi.';

COMMENT ON COLUMN app.users.status IS 'Trạng thái tài khoản.';

COMMENT ON COLUMN app.users.is_verified IS 'Bản đồng bộ kết quả xác minh đáng tin cậy.';

COMMENT ON COLUMN app.users.student_id IS 'MSSV tùy chọn, không có trong projection công khai.';

COMMENT ON COLUMN app.users.failed_login_count IS 'Số lần sai liên tiếp.';

COMMENT ON COLUMN app.users.login_locked_until IS 'Khóa đăng nhập tạm thời 15 phút; khác BANNED.';

COMMENT ON COLUMN app.users.ban_reason IS 'Lý do khóa bởi Admin.';

COMMENT ON COLUMN app.users.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE private.user_contacts (
  user_id uuid PRIMARY KEY NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  university_email varchar(254) NOT NULL UNIQUE CHECK (university_email = lower(btrim(university_email)) AND university_email ~ '^[^@[:space:]]+@[^@[:space:]]+$'),
  email_domain varchar(253) NOT NULL REFERENCES app.university_domains(domain) ON DELETE RESTRICT,
  phone_number varchar(10) CHECK (phone_number ~ '^[0-9]{10}$'),
  CONSTRAINT user_contact_domain CHECK (split_part(university_email,'@',2) = email_domain)
);

COMMENT ON COLUMN private.user_contacts.user_id IS 'Mỗi profile có đúng một bản ghi liên hệ.';

COMMENT ON COLUMN private.user_contacts.university_email IS 'Email trường chuẩn hóa; nguồn liên hệ Claimant sau ACCEPT.';

COMMENT ON COLUMN private.user_contacts.email_domain IS 'Tên miền trường đã đăng ký.';

COMMENT ON COLUMN private.user_contacts.phone_number IS 'Số điện thoại nếu có.';

CREATE TABLE app.sessions (
  session_id uuid PRIMARY KEY NOT NULL,
  user_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CONSTRAINT sessions_time CHECK (expires_at > created_at AND (revoked_at IS NULL OR revoked_at >= created_at))
);

COMMENT ON COLUMN app.sessions.session_id IS 'Session ID từ Auth adapter, không sinh ID không khớp token.';

COMMENT ON COLUMN app.sessions.user_id IS 'Chủ phiên.';

COMMENT ON COLUMN app.sessions.created_at IS 'Thời điểm tạo, lưu UTC.';

COMMENT ON COLUMN app.sessions.expires_at IS 'Hạn phiên/token đang theo dõi.';

COMMENT ON COLUMN app.sessions.revoked_at IS 'Có giá trị khi logout hoặc khóa tài khoản.';

CREATE TABLE app.posts (
  post_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  owner_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  campus_id uuid NOT NULL REFERENCES app.campuses(campus_id) ON DELETE RESTRICT,
  category_id uuid NOT NULL REFERENCES app.categories(category_id) ON DELETE RESTRICT,
  post_type varchar(5) NOT NULL CHECK (post_type IN ('LOST','FOUND')),
  title varchar(200) NOT NULL CHECK (btrim(title) <> ''),
  description text,
  location_detail text,
  incident_at timestamptz NOT NULL,
  verification_question text,
  reward_amount numeric(12,2) CHECK (reward_amount >= 0),
  status varchar(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','RESOLVED','REPORTED','CLOSED')),
  previous_status varchar(10),
  close_reason varchar(20),
  closure_note text,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  search_vector tsvector NOT NULL GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, title || ' ' || coalesce(description,'') || ' ' || coalesce(location_detail,''))) STORED,
  CONSTRAINT posts_subtype CHECK ((post_type = 'FOUND' AND nullif(btrim(verification_question),'') IS NOT NULL AND reward_amount IS NULL) OR (post_type = 'LOST' AND verification_question IS NULL)),
  CONSTRAINT posts_previous CHECK ((status = 'REPORTED' AND previous_status IS NOT NULL AND previous_status IN ('ACTIVE','RESOLVED')) OR (status <> 'REPORTED' AND previous_status IS NULL)),
  CONSTRAINT posts_closure CHECK ((status = 'CLOSED' AND close_reason IS NOT NULL AND close_reason IN ('OWNER_DELETED','ADMIN_REMOVED') AND closed_at IS NOT NULL AND (close_reason <> 'ADMIN_REMOVED' OR nullif(btrim(closure_note),'') IS NOT NULL)) OR (status <> 'CLOSED' AND close_reason IS NULL AND closed_at IS NULL AND closure_note IS NULL))
);

COMMENT ON COLUMN app.posts.post_id IS 'Định danh bài.';

COMMENT ON COLUMN app.posts.owner_id IS 'Chủ bài.';

COMMENT ON COLUMN app.posts.campus_id IS 'Cơ sở xảy ra sự việc.';

COMMENT ON COLUMN app.posts.category_id IS 'Danh mục vật phẩm.';

COMMENT ON COLUMN app.posts.post_type IS 'Loại bài, độc lập vòng đời.';

COMMENT ON COLUMN app.posts.title IS 'Tiêu đề tìm kiếm.';

COMMENT ON COLUMN app.posts.description IS 'Mô tả tùy chọn.';

COMMENT ON COLUMN app.posts.location_detail IS 'Vị trí chi tiết tùy chọn.';

COMMENT ON COLUMN app.posts.incident_at IS 'Thời gian mất/nhặt, không được ở tương lai khi ghi.';

COMMENT ON COLUMN app.posts.verification_question IS 'Bắt buộc với FOUND, NULL với LOST.';

COMMENT ON COLUMN app.posts.reward_amount IS 'Hậu tạ tùy chọn của LOST.';

COMMENT ON COLUMN app.posts.status IS 'Vòng đời theo OOD.';

COMMENT ON COLUMN app.posts.previous_status IS 'Chỉ có khi REPORTED để khôi phục đúng trạng thái.';

COMMENT ON COLUMN app.posts.close_reason IS 'OWNER_DELETED hoặc ADMIN_REMOVED.';

COMMENT ON COLUMN app.posts.closure_note IS 'Lý do gỡ; không đưa vào kết quả công khai.';

COMMENT ON COLUMN app.posts.closed_at IS 'Thời điểm đóng.';

COMMENT ON COLUMN app.posts.created_at IS 'Thời điểm tạo, lưu UTC.';

COMMENT ON COLUMN app.posts.updated_at IS 'Thời điểm cập nhật.';

COMMENT ON COLUMN app.posts.search_vector IS 'Projection tìm kiếm được tính từ nội dung công khai.';

CREATE TABLE private.post_details (
  post_id uuid PRIMARY KEY NOT NULL REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  contact_kind varchar(5) NOT NULL CHECK (contact_kind IN ('PHONE','EMAIL')),
  contact_value varchar(254) NOT NULL,
  private_identifier text,
  storage_location text,
  CONSTRAINT post_contact_value CHECK ((contact_kind = 'PHONE' AND contact_value ~ '^[0-9]{10}$') OR (contact_kind = 'EMAIL' AND contact_value ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'))
);

COMMENT ON COLUMN private.post_details.post_id IS 'Đúng một bản ghi trên Post tại commit.';

COMMENT ON COLUMN private.post_details.contact_kind IS 'Loại liên hệ.';

COMMENT ON COLUMN private.post_details.contact_value IS 'Liên hệ hợp lệ, không nằm trong public_posts.';

COMMENT ON COLUMN private.post_details.private_identifier IS 'Đặc điểm nhận dạng kín của LOST.';

COMMENT ON COLUMN private.post_details.storage_location IS 'Nơi giữ đồ của FOUND; không công khai.';

CREATE TABLE app.post_images (
  image_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  position smallint NOT NULL CHECK (position BETWEEN 1 AND 5),
  object_key text NOT NULL UNIQUE CHECK (btrim(object_key) <> ''),
  mime_type varchar(10) NOT NULL CHECK (mime_type IN ('image/jpeg','image/png')),
  size_bytes integer NOT NULL CHECK (size_bytes BETWEEN 1 AND 5242880),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT post_images_position UNIQUE (post_id, position)
);

COMMENT ON COLUMN app.post_images.image_id IS 'Định danh ảnh.';

COMMENT ON COLUMN app.post_images.post_id IS 'Bài chứa ảnh.';

COMMENT ON COLUMN app.post_images.position IS 'Vị trí gallery 1–5.';

COMMENT ON COLUMN app.post_images.object_key IS 'Object key trong post-images; không lưu signed URL.';

COMMENT ON COLUMN app.post_images.mime_type IS 'MIME đã kiểm tra từ nội dung file.';

COMMENT ON COLUMN app.post_images.size_bytes IS 'Dung lượng thực tế.';

COMMENT ON COLUMN app.post_images.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE app.claims (
  claim_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  claimant_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  security_answer text,
  claim_message text,
  proof_object_key text UNIQUE,
  proof_mime_type varchar(10),
  proof_size_bytes integer,
  status varchar(10) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACCEPTED','REJECTED','CANCELLED')),
  decision_reason text,
  decided_at timestamptz,
  submitted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT claim_proof CHECK ((proof_object_key IS NULL AND proof_mime_type IS NULL AND proof_size_bytes IS NULL) OR (proof_object_key IS NOT NULL AND btrim(proof_object_key) <> '' AND proof_mime_type IS NOT NULL AND proof_mime_type IN ('image/jpeg','image/png') AND proof_size_bytes IS NOT NULL AND proof_size_bytes BETWEEN 1 AND 5242880)),
  CONSTRAINT claim_decision CHECK ((status = 'PENDING' AND decided_at IS NULL AND decision_reason IS NULL) OR (status <> 'PENDING' AND decided_at IS NOT NULL AND decided_at >= submitted_at AND (status <> 'CANCELLED' OR nullif(btrim(decision_reason),'') IS NOT NULL)))
);

COMMENT ON COLUMN app.claims.claim_id IS 'Định danh Claim.';

COMMENT ON COLUMN app.claims.post_id IS 'Bài nhận Claim.';

COMMENT ON COLUMN app.claims.claimant_id IS 'Người gửi.';

COMMENT ON COLUMN app.claims.security_answer IS 'Bắt buộc với bài FOUND.';

COMMENT ON COLUMN app.claims.claim_message IS 'Mô tả nơi nhặt với LOST.';

COMMENT ON COLUMN app.claims.proof_object_key IS 'Một ảnh trong claim-evidence riêng tư.';

COMMENT ON COLUMN app.claims.proof_mime_type IS 'MIME của bằng chứng nếu có.';

COMMENT ON COLUMN app.claims.proof_size_bytes IS 'Dung lượng bằng chứng nếu có.';

COMMENT ON COLUMN app.claims.status IS 'Máy trạng thái Claim.';

COMMENT ON COLUMN app.claims.decision_reason IS 'Lý do từ chối tùy chọn; hủy có mã nguyên nhân.';

COMMENT ON COLUMN app.claims.decided_at IS 'Có khi không còn PENDING.';

COMMENT ON COLUMN app.claims.submitted_at IS 'Thời điểm gửi.';

CREATE TABLE app.moderation_actions (
  action_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  admin_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  post_id uuid REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  target_user_id uuid REFERENCES app.users(user_id) ON DELETE RESTRICT,
  action varchar(12) NOT NULL CHECK (action IN ('KEEP_POST','REMOVE_POST','BAN_USER')),
  reason text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT moderation_target CHECK ((action IN ('KEEP_POST','REMOVE_POST') AND post_id IS NOT NULL AND target_user_id IS NULL) OR (action = 'BAN_USER' AND target_user_id IS NOT NULL AND post_id IS NULL)),
  CONSTRAINT moderation_reason CHECK (action = 'KEEP_POST' OR nullif(btrim(reason),'') IS NOT NULL)
);

COMMENT ON COLUMN app.moderation_actions.action_id IS 'Định danh audit.';

COMMENT ON COLUMN app.moderation_actions.admin_id IS 'Admin thực hiện.';

COMMENT ON COLUMN app.moderation_actions.post_id IS 'Đích là bài khi KEEP/REMOVE.';

COMMENT ON COLUMN app.moderation_actions.target_user_id IS 'Đích tài khoản khi BAN_USER.';

COMMENT ON COLUMN app.moderation_actions.action IS 'Loại thao tác.';

COMMENT ON COLUMN app.moderation_actions.reason IS 'Lý do bắt buộc cho gỡ/khóa.';

COMMENT ON COLUMN app.moderation_actions.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE app.reports (
  report_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  reporter_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  reason varchar(12) NOT NULL CHECK (reason IN ('SPAM','FALSE_INFO','INAPPROPRIATE','OTHER')),
  detail_message text,
  status varchar(10) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','DISMISSED')),
  action_id uuid REFERENCES app.moderation_actions(action_id) ON DELETE RESTRICT,
  reported_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT report_once UNIQUE (post_id, reporter_id),
  CONSTRAINT report_other CHECK (reason <> 'OTHER' OR nullif(btrim(detail_message),'') IS NOT NULL),
  CONSTRAINT report_settlement CHECK ((status = 'PENDING' AND action_id IS NULL) OR (status <> 'PENDING' AND action_id IS NOT NULL))
);

COMMENT ON COLUMN app.reports.report_id IS 'Định danh báo cáo.';

COMMENT ON COLUMN app.reports.post_id IS 'Bài bị báo cáo.';

COMMENT ON COLUMN app.reports.reporter_id IS 'Người báo cáo.';

COMMENT ON COLUMN app.reports.reason IS 'Lý do báo cáo.';

COMMENT ON COLUMN app.reports.detail_message IS 'OTHER bắt buộc có mô tả.';

COMMENT ON COLUMN app.reports.status IS 'Trạng thái xét báo cáo.';

COMMENT ON COLUMN app.reports.action_id IS 'Audit đã xử lý báo cáo.';

COMMENT ON COLUMN app.reports.reported_at IS 'Thời điểm báo cáo.';

CREATE TABLE app.notifications (
  notification_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  recipient_id uuid NOT NULL REFERENCES app.users(user_id) ON DELETE RESTRICT,
  post_id uuid REFERENCES app.posts(post_id) ON DELETE RESTRICT,
  claim_id uuid REFERENCES app.claims(claim_id) ON DELETE RESTRICT,
  event_type varchar(24) NOT NULL CHECK (event_type IN ('CLAIM_RECEIVED','CLAIM_DECIDED','POST_MODERATED','ACCOUNT_BANNED')),
  message_code varchar(50) NOT NULL CHECK (message_code IN ('CLAIM_RECEIVED','CLAIM_ACCEPTED','CLAIM_REJECTED','CLAIM_CANCELLED','POST_REPORTED','POST_KEPT','POST_REMOVED','ACCOUNT_BANNED')),
  read_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT notification_time CHECK (read_at IS NULL OR read_at >= created_at),
  CONSTRAINT notification_message_event CHECK ((event_type = 'CLAIM_RECEIVED' AND message_code = 'CLAIM_RECEIVED') OR (event_type = 'CLAIM_DECIDED' AND message_code IN ('CLAIM_ACCEPTED','CLAIM_REJECTED','CLAIM_CANCELLED')) OR (event_type = 'POST_MODERATED' AND message_code IN ('POST_REPORTED','POST_KEPT','POST_REMOVED')) OR (event_type = 'ACCOUNT_BANNED' AND message_code = 'ACCOUNT_BANNED')),
  CONSTRAINT notification_context CHECK ((event_type IN ('CLAIM_RECEIVED','CLAIM_DECIDED') AND claim_id IS NOT NULL AND post_id IS NOT NULL) OR (event_type = 'POST_MODERATED' AND post_id IS NOT NULL AND claim_id IS NULL) OR (event_type = 'ACCOUNT_BANNED' AND post_id IS NULL AND claim_id IS NULL))
);

COMMENT ON COLUMN app.notifications.notification_id IS 'Định danh thông báo.';

COMMENT ON COLUMN app.notifications.recipient_id IS 'Người nhận.';

COMMENT ON COLUMN app.notifications.post_id IS 'Ngữ cảnh bài nếu có.';

COMMENT ON COLUMN app.notifications.claim_id IS 'Ngữ cảnh Claim nếu có.';

COMMENT ON COLUMN app.notifications.event_type IS 'Loại sự kiện.';

COMMENT ON COLUMN app.notifications.message_code IS 'Mã thông điệp để UI dựng nội dung, không lưu payload liên hệ.';

COMMENT ON COLUMN app.notifications.read_at IS 'NULL là chưa đọc.';

COMMENT ON COLUMN app.notifications.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE private.school_requests (
  request_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  university_name varchar(200) NOT NULL CHECK (btrim(university_name) <> ''),
  email_domain varchar(253) NOT NULL CHECK (email_domain = lower(email_domain) AND email_domain ~ '^[a-z0-9][a-z0-9.-]*[.]edu[.]vn$'),
  contact_name varchar(150) NOT NULL CHECK (btrim(contact_name) <> ''),
  contact_email varchar(254) NOT NULL CHECK (contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'),
  notes text,
  status varchar(10) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED')),
  reviewer_id uuid REFERENCES app.users(user_id) ON DELETE RESTRICT,
  university_id uuid REFERENCES app.universities(university_id) ON DELETE RESTRICT,
  rejection_reason text,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT school_request_decision CHECK ((status = 'PENDING' AND reviewer_id IS NULL AND university_id IS NULL AND reviewed_at IS NULL AND rejection_reason IS NULL) OR (status = 'APPROVED' AND reviewer_id IS NOT NULL AND university_id IS NOT NULL AND reviewed_at IS NOT NULL AND rejection_reason IS NULL) OR (status = 'REJECTED' AND reviewer_id IS NOT NULL AND university_id IS NULL AND reviewed_at IS NOT NULL AND nullif(btrim(rejection_reason),'') IS NOT NULL))
);

COMMENT ON COLUMN private.school_requests.request_id IS 'Mã yêu cầu trả về người gửi.';

COMMENT ON COLUMN private.school_requests.university_name IS 'Tên trường đề nghị.';

COMMENT ON COLUMN private.school_requests.email_domain IS 'Tên miền xin tham gia, chuẩn hóa.';

COMMENT ON COLUMN private.school_requests.contact_name IS 'Người liên hệ của trường.';

COMMENT ON COLUMN private.school_requests.contact_email IS 'Email nhận kết quả, chỉ Admin/Auth mail adapter đọc.';

COMMENT ON COLUMN private.school_requests.notes IS 'Ghi chú tùy chọn.';

COMMENT ON COLUMN private.school_requests.status IS 'Vòng đời yêu cầu.';

COMMENT ON COLUMN private.school_requests.reviewer_id IS 'Admin quyết định.';

COMMENT ON COLUMN private.school_requests.university_id IS 'Trường được tạo khi APPROVED.';

COMMENT ON COLUMN private.school_requests.rejection_reason IS 'Bắt buộc khi REJECTED.';

COMMENT ON COLUMN private.school_requests.reviewed_at IS 'Thời điểm quyết định.';

COMMENT ON COLUMN private.school_requests.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE TABLE private.school_request_campuses (
  request_campus_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL REFERENCES private.school_requests(request_id) ON DELETE RESTRICT,
  name varchar(150) NOT NULL CHECK (btrim(name) <> ''),
  address text NOT NULL CHECK (btrim(address) <> '')
);

COMMENT ON COLUMN private.school_request_campuses.request_campus_id IS 'Định danh dòng cơ sở đề nghị.';

COMMENT ON COLUMN private.school_request_campuses.request_id IS 'Yêu cầu chứa cơ sở.';

COMMENT ON COLUMN private.school_request_campuses.name IS 'Tên cơ sở đề nghị.';

COMMENT ON COLUMN private.school_request_campuses.address IS 'Địa chỉ đề nghị.';

CREATE TABLE app.integration_tasks (
  task_id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  kind varchar(24) NOT NULL CHECK (kind IN ('REVOKE_SESSIONS','DELETE_OBJECT','SCHOOL_DECISION_EMAIL')),
  target_user_id uuid REFERENCES app.users(user_id) ON DELETE RESTRICT,
  request_id uuid REFERENCES private.school_requests(request_id) ON DELETE RESTRICT,
  object_key text,
  status varchar(8) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','DONE','FAILED')),
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  last_error_code varchar(50),
  next_attempt_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT integration_target CHECK ((kind = 'REVOKE_SESSIONS' AND target_user_id IS NOT NULL AND request_id IS NULL AND object_key IS NULL) OR (kind = 'SCHOOL_DECISION_EMAIL' AND request_id IS NOT NULL AND target_user_id IS NULL AND object_key IS NULL) OR (kind = 'DELETE_OBJECT' AND object_key IS NOT NULL AND btrim(object_key) <> '' AND target_user_id IS NULL AND request_id IS NULL))
);

COMMENT ON COLUMN app.integration_tasks.task_id IS 'Định danh tác vụ tích hợp.';

COMMENT ON COLUMN app.integration_tasks.kind IS 'Loại thao tác.';

COMMENT ON COLUMN app.integration_tasks.target_user_id IS 'Đích thu hồi phiên.';

COMMENT ON COLUMN app.integration_tasks.request_id IS 'Đích gửi kết quả trường.';

COMMENT ON COLUMN app.integration_tasks.object_key IS 'Đích dọn object Storage.';

COMMENT ON COLUMN app.integration_tasks.status IS 'Trạng thái thử lại.';

COMMENT ON COLUMN app.integration_tasks.attempt_count IS 'Số lần thử.';

COMMENT ON COLUMN app.integration_tasks.last_error_code IS 'Mã lỗi đã làm sạch, không chứa PII.';

COMMENT ON COLUMN app.integration_tasks.next_attempt_at IS 'Thời điểm được phép thử lại.';

COMMENT ON COLUMN app.integration_tasks.created_at IS 'Thời điểm tạo, lưu UTC.';

CREATE UNIQUE INDEX campus_name_uq ON app.campuses (university_id, lower(name));

CREATE UNIQUE INDEX category_name_uq ON app.categories (lower(name));

CREATE INDEX domain_university_idx ON app.university_domains (university_id);

CREATE INDEX session_user_idx ON app.sessions (user_id, expires_at);

CREATE INDEX post_owner_idx ON app.posts (owner_id, created_at DESC, post_id DESC);

CREATE INDEX post_feed_idx ON app.posts (created_at DESC, post_id DESC) WHERE status IN ('ACTIVE','RESOLVED');

CREATE INDEX post_campus_idx ON app.posts (campus_id, incident_at, created_at DESC) WHERE status IN ('ACTIVE','RESOLVED');

CREATE INDEX post_category_idx ON app.posts (category_id, incident_at) WHERE status IN ('ACTIVE','RESOLVED');

CREATE INDEX post_type_idx ON app.posts (post_type, created_at DESC, post_id DESC) WHERE status IN ('ACTIVE','RESOLVED');

CREATE INDEX post_search_gin ON app.posts USING gin (search_vector);

CREATE INDEX post_queue_idx ON app.posts (post_id) WHERE status = 'REPORTED';

CREATE UNIQUE INDEX claim_pending_uq ON app.claims (post_id, claimant_id) WHERE status = 'PENDING';

CREATE UNIQUE INDEX claim_accepted_uq ON app.claims (post_id) WHERE status = 'ACCEPTED';

CREATE INDEX claim_post_idx ON app.claims (post_id, submitted_at DESC, claim_id);

CREATE INDEX claim_user_idx ON app.claims (claimant_id, status);

CREATE INDEX report_pending_idx ON app.reports (post_id) WHERE status = 'PENDING';

CREATE INDEX report_reporter_idx ON app.reports (reporter_id);

CREATE INDEX notification_user_idx ON app.notifications (recipient_id, created_at DESC, notification_id DESC);

CREATE INDEX notification_unread_idx ON app.notifications (recipient_id) WHERE read_at IS NULL;

CREATE UNIQUE INDEX request_pending_uq ON private.school_requests (email_domain) WHERE status = 'PENDING';

CREATE UNIQUE INDEX request_campus_uq ON private.school_request_campuses (request_id, lower(name));

CREATE INDEX request_queue_idx ON private.school_requests (created_at, request_id) WHERE status = 'PENDING';

CREATE INDEX audit_post_idx ON app.moderation_actions (post_id, created_at DESC) WHERE post_id IS NOT NULL;

CREATE INDEX audit_user_idx ON app.moderation_actions (target_user_id, created_at DESC) WHERE target_user_id IS NOT NULL;

CREATE INDEX task_retry_idx ON app.integration_tasks (next_attempt_at, task_id) WHERE status IN ('PENDING','FAILED');
